" role=\"img\" aria-label=\"Scatter plot: turn time in seconds versus response tokens per second\">';for(let i=0;i<=4;i++){const x=left+i*w/4,y=bottom-i*h/4;svg+=`<line class=\"gridline\" x1=\"${left}\" y1=\"${y}\" x2=\"${right}\" y2=\"${y}\"/><text x=\"${left-9}\" y=\"${y+4}\" text-anchor=\"end\">${fmt(ymax*i/4)}</text><text x=\"${x}\" y=\"${bottom+20}\" text-anchor=\"middle\">${fmt(xmax*i/4)}</text>`;}svg+=`<line class=\"baseline\" x1=\"${left}\" y1=\"${bottom}\" x2=\"${right}\" y2=\"${bottom}\"/>`;rows.forEach(r=>{const x=left+r.seconds/xmax*w,y=bottom-r.value/ymax*h,color=`var(--model${r.index%5})`,label=r.model+' \u00b7 '+r.name+' \u00b7 '+fmt(r.seconds)+' s \u00b7 '+fmt(r.value)+' response tokens/s \u00b7 n='+r.count;svg+=`<circle class=\"point\" tabindex=\"0\" cx=\"${x}\" cy=\"${y}\" r=\"6\" fill=\"${r.speed==='fast'?color:'none'}\" stroke=\"${color}\" stroke-width=\"2.5\" aria-label=\"${esc(label)}\"><title>${esc(label)}</title></circle>`;});svg+='<text class=\"axis-label\" x=\"394\" y=\"275\" text-anchor=\"middle\">Mean turn time (seconds)</text><text class=\"axis-label\" transform=\"translate(15 130) rotate(-90)\" text-anchor=\"middle\">Mean response tokens/s</text></svg>';$('effortGraph').innerHTML=svg;$('scatterLegend').innerHTML=data.models.filter(m=>filter==='all'||filter===m.name).map(m=>`<span><i class=\"legend-mark\" style=\"--mark:var(--model${data.models.indexOf(m)%5})\"></i>${esc(m.name)}</span>`).join('')+'<span><i class=\"legend-open\"></i>Standard</span><span><i class=\"legend-solid\"></i>Fast</span>';$('effortGraphScale').textContent='Each point shows mean speed and mean turn time for up to 3 comparable runs; open circles are Standard, filled circles are Fast.';}\nfunction renderGraphs(){const effort=$('graphEffort').value,model=$('graphModel').value;plotBars(effort);plotScatter(effort,model);}\n$('graphEffort').addEventListener('change',renderGraphs);$('graphModel').addEventListener('change',renderGraphs);\nlet selected=(()=>{const r=data.results.find(x=>x.effort!=='ultra'&&x.status==='completed');const m=data.models[0];return r?{model:r.model,effort:r.effort,speed:r.speed}:{model:m.name,effort:allEfforts[0],speed:'standard'};})();\nfunction cell(m,e,s){const speed=s==='fast'?'Fast':'Standard';if(!supports(m,e,s))return `<div class=\"rate-button\"><span class=\"speed\">${speed}</span><span class=\"status\">Unsupported</span></div>`;const rate=graphRate(m.name,e,s);const value=rate.value==null?(rate.status==='\u2014'?'Unmeasured':rate.status):fmt(rate.value);const style=rate.status==='429'?'rate':rate.status==='Failed'?'failed':'';const active=selected.model===m.name&&selected.effort===e&&selected.speed===s;return `<button class=\"rate-button ${active?'active':''}\" data-model=\"${esc(m.name)}\" data-effort=\"${esc(e)}\" data-speed=\"${s}\" aria-label=\"${esc(m.name+', '+effortLabel[e]+', '+speed+': '+value+(rate.count?', average of '+rate.count+' runs':''))}\" aria-pressed=\"${active}\"><span class=\"speed\">${speed}</span><span class=\"rate-summary\"><strong class=\"${style?'status '+style:''}\">${esc(value)}</strong>${rate.count?`<small class=\"sample-count\">n=${rate.count}</small>`:''}</span></button>`;}\nfunction renderMatrix(){const model=$('modelFilter').value,effort=$('effortFilter').value;const columns=allEfforts.filter(e=>effort==='all'||effort===e);$('headRow').innerHTML='<th scope=\"col\">Model</th>'+columns.map(e=>`<th scope=\"col\">${esc(effortLabel[e])}</th>`).join('');let html='';for(const m of data.models){if(model!=='all'&&model!==m.name)continue;html+=`<tr><th scope=\"row\" class=\"model\">${esc(m.name)}</th>`+columns.map(e=>`<td>${cell(m,e,'standard')}${cell(m,e,'fast')}</td>`).join('')+'</tr>';}$('matrix').innerHTML=html||`<tr><td colspan=\"${columns.length+1}\">No matching configurations.</td></tr>`;}\nfunction renderDetails(){const {model,effort,speed}=selected;const rows=results(model,effort,speed),included=sample(model,effort,speed);$('detailTitle').textContent=model;$('detailTags').textContent=effortLabel[effort]+' \u00b7 '+(speed==='fast'?'Fast':'Standard')+' \u00b7 '+included.length+' in average \u00b7 '+rows.length+' saved '+(rows.length===1?'run':'runs');if(!rows.length){$('records').innerHTML='<div class=\"empty\">No saved attempt for this configuration yet.</div>';return;}$('records').innerHTML=rows.map((r,i)=>{const label=r.status==='completed'?(r.passed===true?'Completed \u00b7 passed':r.passed===false?'Completed \u00b7 check failed':'Completed'):r.status==='429'?'429 \u00b7 provider error':'Failed';return `<article class=\"record\"><h3>${included.includes(r)?'In average \u00b7 ':i===0?'Latest \u00b7 ':''}${esc(r.task)} \u00b7 repetition ${esc(r.rep)}</h3><span class=\"status ${r.status==='429'?'rate':r.status==='failed'?'failed':''}\">${esc(label)}</span><div class=\"rates\"><div><span class=\"rate-value\">${fmt(r.response)}</span><span class=\"rate-label\">response tokens/s</span></div><div><span class=\"rate-value\">${fmt(r.total)}</span><span class=\"rate-label\">total tokens/s</span></div></div><p class=\"meta\">${esc(r.source)} \u00b7 ${esc(time(r.time))}<br>Turn wall: ${r.seconds==null?'\u2014':fmt(r.seconds)+' s'} \u00b7 Task version: ${esc(r.taskVersion||'unavailable')}</p></article>`;}).join('');}\n$('matrix').addEventListener('click',e=>{const b=e.target.closest('button[data-model]');if(!b)return;selected={model:b.dataset.model,effort:b.dataset.effort,speed:b.dataset.speed};renderMatrix();renderDetails();const active=$('matrix').querySelector('button.active');if(active)active.focus({preventScroll:true});});\nfor(const id of ['modelFilter','effortFilter'])$(id).addEventListener('change',renderMatrix);\nrenderGraphs();renderMatrix();renderDetails();\n</script>\n</body></html>\n";
export default { async fetch() { return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } }); } };
